args.content:
SELECT ?item ?itemLabel WHERE {
  ?item wdt:P31 wd:Q17143821 ;  # point of interest
        wdt:P625 ?coords.
  OPTIONAL {
    ?item wdt:P131 wd:Q8813.  # located in Alicante
  }
  SERVICE wikibase:label {
    bd:serviceParam wikibase:language "en".
  }
}

